sed -i '/fun updateLotteryStatus(id: String, status: LotteryStatus, winAmount: Double) {/,/}/c \    fun updateLotteryStatus(id: String, status: LotteryStatus, winAmount: Double) {\n        viewModelScope.launch {\n            val rec = lotteryRecords.value.find { it.id == id }\n            if (rec != null) {\n                repository.updateLottery(rec.copy(status = status, winAmount = winAmount))\n                _snackbarEvent.emit("🎯 彩票单状态已更新为: ${status.label}")\n            }\n        }\n    }' app/src/main/java/com/example/ui/ExpenseViewModel.kt

sed -i '/_lotteryRecords.value = _lotteryRecords.value.map { rec ->/,/}/c \                    results.forEach { res ->\n                        val rec = lotteryRecords.value.find { it.id == res.recordId }\n                        if (rec != null) {\n                            repository.updateLottery(rec.copy(status = res.status, winAmount = res.winAmount))\n                        }\n                    }' app/src/main/java/com/example/ui/ExpenseViewModel.kt
